#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int *value = malloc(sizeof *value);
    if (value == NULL) {
        fputs("allocation failed\n", stderr);
        return 1;
    }
    *value = 42;
    printf("value=%d\n", *value);
    free(value);
    return 0;
}
